import { USERS, expect, test, uniqueName } from "../../fixtures";

test.describe("vendor audit trail", () => {
  test(
    "audit events are listed oldest first with actor and action",
    { tag: "@AUD-01" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorName = uniqueName("Audit Vendor");

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "services",
          contact_email: `audit-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@example.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n% audit trail test w9\n%%EOF\n"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);

      // Act: extraction may complete asynchronously, so poll until it is recorded.
      const fetchTrail = async () => {
        const response = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(response.status()).toBe(200);
        return (await response.json()) as {
          items: Array<{
            id: number;
            action: string;
            actor: { id: string; name: string; email: string };
            at: string;
            details: Record<string, unknown>;
          }>;
        };
      };

      await expect
        .poll(async () => (await fetchTrail()).items.map((e) => e.action), {
          timeout: 60_000,
          intervals: [500, 1000, 2000],
        })
        .toContain("document.extracted");

      const trail = await fetchTrail();

      // Assert
      expect(trail.items.map((e) => e.action)).toEqual([
        "vendor.created",
        "document.uploaded",
        "document.extracted",
      ]);

      for (const event of trail.items) {
        expect(event.actor.email).toBe(USERS.member);
        expect(event.actor.name).toBeTruthy();
        expect(event.at).toMatch(/^\d{4}-\d{2}-\d{2}T/);
        expect(Number.isNaN(Date.parse(event.at))).toBe(false);
      }

      const timestamps = trail.items.map((e) => Date.parse(e.at));
      const sorted = [...timestamps].sort((a, b) => a - b);
      expect(timestamps).toEqual(sorted);
    },
  );
});
